const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.message}"/></svg>`;
const levelNames={municipal:'Municipal',provincial:'Provincial / territorial',federal:'Federal',school:'School authority',community:'Indigenous / community'};
const initial=()=>({province:'',city:'',municipality:'',ward:'',postal:'',provRiding:'',fedRiding:'',schoolBoard:'',locationConfirmed:true,directoryAdded:[],issue:'',serviceDetail:'',levels:[],opposition:false,selected:[],recipientModes:{},custom:[],liveReps:[],liveChosen:[],topic:'',concern:'',impact:'',request:'',name:'',tone:'respectful',language:'en',includePostal:false,subject:'',body:'',emailApp:'default',draftContext:''});
let state=initial(),step=0,editor='guide',lookup=null,lookupError='',lookupPending=false,lookupToken='',lookupAbort=null,lookupResult=null,lookupOffline=false,lookupStatus='',lookupUpdated=null,lookupInteracted=false,installPrompt;
let locationPending=false,locationStatus='',locationRequest=0,locationAbort=null,rememberLocation=false;
try{const remembered=L.savedLocation(JSON.parse(localStorage.getItem('civicpost-location-v1')||'null'));if(remembered){Object.assign(state,remembered);rememberLocation=true;locationStatus='Your saved location is filled in. Review it if you have moved.';}}catch{}
let saved=[];try{const a=JSON.parse(localStorage.getItem('civicpost-drafts-v1')||'[]');if(Array.isArray(a))saved=a.filter(x=>x&&typeof x.title==='string'&&x.state&&typeof x.state==='object').slice(0,10);}catch{}
const notes=(text,kind='')=>`<div class="note ${kind}">${icon(kind==='amber'?'info':'shield')}<span>${text}</span></div>`;
const sourceLabel=c=>({'official':'Official source','association':'Association directory','aggregator':'Open data aggregator','service-directory':'Public service directory'}[c.sourceKind]||'Published source');
const button=(text,action,cls='')=>`<button class="button ${cls}" data-action="${action}">${text}</button>`;
const field=(id,label,placeholder='',type='text')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" data-bind="${id}" type="${type}" maxlength="${['concern','impact','request'].includes(id)?6000:180}" placeholder="${esc(placeholder)}" value="${esc(state[id])}"></div>`;
const area=(id,label,placeholder,rows=3)=>`<div class="field"><label for="${id}">${label}</label><textarea id="${id}" data-bind="${id}" rows="${rows}" maxlength="${id==='body'?18000:6000}" placeholder="${esc(placeholder)}" ${id==='body'?'class="draft-area"':''}>${esc(state[id])}</textarea></div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function saveList(){try{localStorage.setItem('civicpost-drafts-v1',JSON.stringify(saved));$('#draft-count').textContent=saved.length;return true;}catch{toast('This browser could not save the draft. Copy your message before closing.');return false;}}
function invalidate(){state.selected=[];state.recipientModes={};state.directoryAdded=[];}
function clearLookup(){state.liveReps=[];state.liveChosen=[];lookup=null;lookupError='';lookupToken='';lookupPending=false;lookupAbort?.abort();lookupAbort=null;lookupResult=null;lookupOffline=false;lookupStatus='';lookupUpdated=null;lookupInteracted=false;}
function locationAssist(){return `<div class="location-assist"><div class="row"><b>Fill in a starting location</b><button class="button secondary small" data-action="suggest-location" ${locationPending?'disabled':''}>${locationPending?'Finding your city…':'Suggest my city'}</button></div><p class="small muted">Uses your approximate internet location through <a href="https://www.bigdatacloud.com/privacy-and-cookie-policy" target="_blank" rel="noopener noreferrer">BigDataCloud</a>, which receives your IP address. No GPS, name or message is sent. Mobile networks and VPNs can suggest a different city.</p><p class="small" role="status">${esc(locationStatus)}</p>${state.locationConfirmed===false?button('Confirm suggested city','confirm-location','small'):''}</div>`;}
function cancelLocationSuggestion(){locationRequest++;locationAbort?.abort();locationAbort=null;locationPending=false;locationStatus='';}
function persistLocation(){if(!rememberLocation||!locationValid())return;try{localStorage.setItem('civicpost-location-v1',JSON.stringify(L.savedLocation(state)));}catch{toast('Location could not be remembered on this device.');}}
async function suggestLocation(){
 cancelLocationSuggestion();const token=locationRequest;locationPending=true;locationStatus='Checking your approximate city…';locationAbort=new AbortController();const controller=locationAbort;const timer=setTimeout(()=>controller.abort(),10000);render();
 try{const r=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?localityLanguage=en',{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(!r.ok)throw Error('The location service is unavailable. Enter your location manually.');const suggested=L.parseSuggestion(await r.json());if(token!==locationRequest)return;
  clearLookup();invalidate();Object.assign(state,suggested,{municipality:'',ward:'',postal:'',provRiding:'',fedRiding:'',schoolBoard:'',locationConfirmed:false});locationStatus='Approximate city filled in. Confirm it or edit the fields. Ward, riding and school board still need your choice.';
 }catch(e){if(token!==locationRequest)return;locationStatus=e.name==='AbortError'?'Location suggestion timed out. Enter your location manually.':e.message;}finally{clearTimeout(timer);if(token===locationRequest){locationPending=false;locationAbort=null;render();}}
}
function locationValid(){return state.province&&state.city.trim()&&state.locationConfirmed!==false;}
function go(n){if(n>0&&!locationValid()){toast(state.locationConfirmed===false?'Confirm the suggested city or enter your location manually.':'Choose a province or territory and enter your city or community.');return;}if(n>0&&step===0)persistLocation();if(n>1&&(!state.issue||!state.levels.length)){toast('Choose an issue and at least one level of government.');return;}step=n;render();$('#panel').focus({preventScroll:true});if(window.scrollY>200)$('#panel').scrollIntoView({behavior:'smooth',block:'start'});}
function ridingField(id,label,level){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" data-bind="${id}" list="${id}-list" value="${esc(state[id])}" placeholder="Choose or enter your riding" maxlength="180"><datalist id="${id}-list">${E.ridings(state.province,level).map(n=>`<option value="${esc(n)}">`).join('')}</datalist></div>`;}
function locationPanel(){const p=D.provinces.find(p=>p.code===state.province),city=E.cityFor(state);
return `<p class="section-kicker">STEP 01 / WHERE YOU LIVE</p><h2>Start with your community.</h2><p class="panel-intro">Your location helps identify the offices that serve you. Enter it yourself, or use your postal code to find possible districts.</p>
${locationAssist()}<div class="form-grid"><div class="field"><label for="province">Province or territory</label><select id="province" data-bind="province"><option value="">Select province or territory</option>${D.provinces.map(p=>`<option value="${p.code}" ${state.province===p.code?'selected':''}>${p.name}</option>`).join('')}</select></div>
<div class="field"><label for="city">City, town or community</label><input id="city" data-bind="city" list="cities" autocomplete="address-level2" maxlength="100" placeholder="e.g. Edmonton" value="${esc(state.city)}"><datalist id="cities">${E.municipalityNames(state.province).map(name=>`<option value="${esc(name)}">`).join('')}</datalist><small>Any Canadian community can be entered.</small></div></div>
<div class="field"><label for="ward">Municipal ward or district <span class="optional">· optional</span></label><input id="ward" data-bind="ward" list="wards" maxlength="100" placeholder="Choose or enter your ward, if your municipality has one" value="${esc(state.ward)}"><datalist id="wards">${(city?.wards||[]).map(w=>`<option value="${esc(w)}">`).join('')}</datalist><small id="ward-help">${city?`<a href="${esc(city.wardFinder)}" target="_blank" rel="noopener noreferrer">Find your ward on the official city website ↗</a>`:'Not every municipality uses wards. A city name alone cannot identify your riding.'}</small></div>
<details class="details" open><summary>Find my representatives with a postal code</summary><div class="details-content"><div class="field"><label for="postal">Canadian postal code</label><div class="row"><input class="grow" id="postal" data-bind="postal" autocomplete="postal-code" placeholder="A1A 1A1" maxlength="8" value="${esc(state.postal)}"><button class="button secondary small" data-action="lookup" ${lookupPending?'disabled':''}>${lookupPending?'Finding…':'Find districts'}</button></div><small>This checks the downloaded database first, then sends only your postal code to <a href="https://represent.opennorth.ca/" target="_blank" rel="noopener noreferrer">Open North’s Represent service</a>. Your name and message are not sent.</small></div><p class="small muted">${CivicOfflineData.postalCodes.toLocaleString()} full postal codes in the downloaded database. ${button('Offline coverage','offline-coverage','secondary small')}</p><div id="postal-status" class="lookup-status" role="status">${lookupPending?'<span class="spinner"></span> '+esc(lookupStatus||'Reading downloaded database…'):esc(lookupError||lookupStatus)}</div><div id="postal-results">${lookup?lookupChoices():''}${lookupRecovery()}</div></div></details>
<details class="details"><summary>I already know my provincial or federal riding</summary><div class="details-content form-grid">${ridingField('provRiding','Provincial / territorial riding','provincial')}${ridingField('fedRiding','Federal riding','federal')}<p class="small muted full">Choose an exact riding from the directory suggestions to match its published office email. A municipal ward and a riding are different areas. ${p?`<a href="${p.members}" target="_blank" rel="noopener noreferrer">Find your ${p.title} ↗</a> · `:''}<a href="${D.federalMembers}" target="_blank" rel="noopener noreferrer">Find your MP ↗</a></p></div></details>
<details class="details" ${state.schoolBoard?'open':''}><summary>Choose my school board or authority</summary><div class="details-content"><div class="field"><label for="schoolBoard">School board / authority</label><input id="schoolBoard" data-bind="schoolBoard" list="school-boards" value="${esc(state.schoolBoard)}" placeholder="Search the board’s name" maxlength="240"><datalist id="school-boards">${E.jurisdictions(state.province,'school').map(n=>`<option value="${esc(n)}">`).join('')}</datalist><small>Choose your actual board, language and school system. A board’s office city does not define its attendance area. Trustee wards are separate from city wards.</small></div></div></details>
<label class="checkrow"><input type="checkbox" id="remember-location" ${rememberLocation?'checked':''}>Remember my confirmed location on this device</label>${notes('No street address is needed. Location is kept only if you choose to remember it, save a lookup or save a draft. Your unsaved message stays in this session.')}
<div class="actions"><span class="small muted">13 provinces & territories</span>${button('Choose your issue <span>→</span>','next')}</div>`;}
function lookupGroups(level){
 const groups=[];
 for(const r of lookup.reps.filter(r=>r.level===level)){
  const key=level==='municipal'?[r.district,r.set].map(E.norm).join('|'):r.id;
  let group=groups.find(g=>g.key===key);
  if(!group){group={key,first:r,reps:[]};groups.push(group);}group.reps.push(r);
 }
 return groups;
}
function lookupChoices(){
 const result=lookupResult,offline=result?.offline,downloaded=result?.source==='bundled';
 const summary=downloaded?'Downloaded database result':result?.source==='mixed'?'Live update + downloaded database':lookupOffline?'Saved lookup':'Live lookup';
 const levels=['federal','provincial','municipal'];
 const coverage=levels.map(level=>{const reps=lookup.reps.filter(r=>r.level===level),emails=reps.filter(r=>r.email);return `<li><b>${levelNames[level]}:</b> ${reps.length?(emails.length?'District found · email available':'District found · official contact page available'):'No district in this result · use the official finder'}</li>`;}).join('');
 const warnings=[];
 if(offline?.coordinateReview)warnings.push('The postal source names '+offline.coordinateReview.locality+' but places its point in Toronto. District suggestions are withheld. Confirm your community and use the official ward and riding finders.');
 if(offline?.upcomingDistricts?.length)warnings.push('A later boundary edition is installed and will be used from its effective local date. Current districts remain shown until then.');
 if(offline?.expiredDistricts?.length)warnings.push('Some downloaded boundaries have expired: '+[...new Set(offline.expiredDistricts.map(d=>d.city+' (through '+d.validUntil+')'))].join(', ')+'. Use the current official finder.');
 if(offline?.districts?.some(d=>d.status==='member-verification-pending'&&(downloaded||result?.retainedLevels?.includes(d.level))))warnings.push('This district is mapped, but the current officeholder is awaiting verification after an election. An old member email is not substituted.');
 if(result?.changedLevels?.length)warnings.push('The live and downloaded district suggestions differ for '+result.changedLevels.map(l=>levelNames[l]).join(', ')+'. Confirm using the official finder.');
 if(offline?.conflictingCoordinates)warnings.push('This code has conflicting source coordinates. Confirm every district.');
 if(offline?.cities?.length>1)warnings.push('Possible communities: '+offline.cities.join(', ')+'. Enter your actual community above.');
 if(offline)warnings.push(...new Set((offline.districts||[]).filter(d=>downloaded||result?.retainedLevels?.includes(d.level)).map(d=>d.boundaryWarning).filter(Boolean)));
 return `<div class="lookup-result"><p><b>Possible matches near ${esc(lookup.city||state.postal)}</b><br><span class="chip">${summary}</span></p><ul class="lookup-coverage">${coverage}</ul><p class="small">Postal codes can cross boundaries. These are possible matches; confirm each district using its official page.</p>${warnings.length?notes(warnings.map(esc).join('<br>'),'amber'):''}${Object.entries(levelNames).map(([level,label])=>{const groups=lookupGroups(level);if(!groups.length)return '';return `<div class="field"><label for="choose-${level}">${label}</label><select id="choose-${level}" data-lookup-level="${level}"><option value="">Choose / leave unresolved</option>${groups.map(g=>{const r=g.first;return `<option value="${r.id}" ${g.reps.some(x=>state.liveChosen.includes(x.id))?'selected':''}>${esc(r.district)}${g.reps.length>1?' · '+g.reps.length+' office contacts':''}</option>`;}).join('')}</select><small>${groups.map(g=>`<a href="${esc(g.first.source)}" target="_blank" rel="noopener noreferrer">${esc(g.first.district)} ↗</a>`).join(' · ')}</small></div>`;}).join('')}<details class="details"><summary>Sources and lookup limits</summary><div class="details-content"><p class="small">${offline?'Downloaded postal source packaged '+esc(offline.sourceSnapshot)+'. ':''}${lookupOffline&&!downloaded?'Saved API data from '+esc(result.fetchedAt.slice(0,10))+'. ':''}Source dates describe retrieval or packaging; they do not independently verify a residential address. Each office shows its own source. School-board eligibility and Indigenous government affiliation require your choice.</p></div></details></div>`;
}
function issuePanel(){const issue=D.issues.find(i=>i.id===state.issue);return `<p class="section-kicker">STEP 02 / WHAT MATTERS TO YOU</p><h2>What would you like to raise?</h2><p class="panel-intro">Choose the closest topic. We’ll explain where it usually belongs, and you can adjust the suggested level.</p>${['Everyday life','In your community','Across Canada & beyond'].map(group=>`<p class="issue-group">${group}</p><div class="issue-grid">${D.issues.filter(i=>i.group===group).map(i=>`<button class="issue-option ${state.issue===i.id?'active':''}" data-issue="${i.id}" aria-pressed="${state.issue===i.id}">${icon(i.icon)}<span>${i.name}</span></button>`).join('')}</div>`).join('')}${issue?`<div class="divider"></div><h3>Who usually handles this?</h3><p class="small muted">${esc(issue.summary)}</p>${notes(esc(issue.hint))}${issue.id==='waste'?`<div class="field"><label for="serviceDetail">Which local service?</label><select id="serviceDetail" data-bind="serviceDetail">${[['','All / not sure'],['garbage','Garbage, organics and bulky items'],['recycling','Recycling / Blue Box'],['water','Water and sewer']].map(([id,label])=>`<option value="${id}" ${state.serviceDetail===id?'selected':''}>${label}</option>`).join('')}</select><small>Different providers can handle these services. General municipal enquiry contacts may also be shown.</small></div>`:''}<div class="chips">${Object.entries(levelNames).map(([level,name])=>`<label class="checkrow"><input type="checkbox" data-level="${level}" ${state.levels.includes(level)?'checked':''}>${name}</label>`).join('')}</div>`:''}<div class="actions">${button('← Back','back','link')}${button('Find the right offices →','next')}</div>`;}
function contactCard(c){
 const selected=state.selected.includes(c.id),label=c.kind==='shared'?'From shared draft · verify':c.kind==='custom'?'Added by you':c.email?(c.serviceProvider?'Service provider inbox':c.emailType==='office'||c.kind==='curated'?'Office / role inbox':'Published work email'):c.kind==='service-route'?'Official service channel':'Official contact page';
 return `<article class="contact-card ${selected?'selected':''}"><div class="contact-top">${c.email?`<input type="checkbox" aria-label="Select ${esc(c.role)}" data-contact="${esc(c.id)}" ${selected?'checked':''}>`:''}<div class="contact-main"><h3>${esc(c.role)}${c.kind==='directory-contact'&&c.district?' — '+esc(c.district):''}</h3>${c.jurisdiction?`<p class="contact-jurisdiction">${esc(c.jurisdiction)}</p>`:''}${c.name?`<p class="contact-note">${esc(c.name)}</p>`:''}<span class="chip ${c.email?'':'gray'}">${label}</span>${c.specialist?'<span class="chip gray">Specific service only</span>':''}${c.schoolOffice?'<span class="chip gray">Individual school office</span>':''}${c.refreshAfter?'<span class="chip gray">Recheck from '+esc(c.refreshAfter)+'</span>':''}${c.continuityInferred?'<span class="chip gray">Reelected · retained office email</span>':''}${c.officeStaff?'<span class="chip gray">Office staff</span>':''}${c.email?`<span class="contact-email">${esc(c.email)}</span>`:'<p class="contact-note">'+(c.kind==='service-route'?'Follow the service’s published instructions. You can copy your draft into a form where one is provided.':'Use the official directory to confirm this office’s contact.')+'</p>'}<p class="contact-reason">${esc(E.contactRelevance(c,state).reason)}</p>${c.email&&c.servicePurpose?`<p class="small">${esc(c.servicePurpose)}</p>`:''}${c.phone?`<p class="small">Published phone: ${esc(c.phone)}</p>`:''}<details class="contact-source-details"><summary>Contact details and source date</summary><p class="contact-note">${esc(c.note||'')}</p>${c.validUntil?'<p class="small">Current record valid through '+esc(c.validUntil)+'.</p>':''}${c.checked?'<p class="small">Source retrieved '+esc(c.checked)+(c.sourceDate?' · Source date '+esc(c.sourceDate):'')+'</p>':''}</details><div class="contact-meta"><a href="${esc(E.safeURL(c.source))}" target="_blank" rel="noopener noreferrer">${c.email?'Check source':c.contactLabel||'Open official contact page'} ↗</a>${c.email?`<select class="recipient-mode" data-mode="${esc(c.id)}" aria-label="Recipient type for ${esc(c.role)}"><option value="to" ${(state.recipientModes[c.id]||'to')==='to'?'selected':''}>To</option><option value="cc" ${state.recipientModes[c.id]==='cc'?'selected':''}>Cc</option></select>`:''}</div>${c.sourceKind&&c.sourceKind!=='official'?'<p class="small muted">'+esc(sourceLabel(c))+'</p>':''}</div></div></article>`;
}
function contactsPanel(){
 const contacts=E.contactsFor(state),count=E.selectedContacts(state).length,groups=E.recipientGroups(state),coverage=E.coverageFor(state);
 const coverageText=coverage.status==='email'?`${coverage.emailCount} published email contact${coverage.emailCount===1?'':'s'} matched${coverage.serviceRouteCount?' · '+coverage.serviceRouteCount+' official service channel'+(coverage.serviceRouteCount===1?'':'s'):''}.`:coverage.status==='service'?'An official service channel is available. No published email matches these choices. You can write a draft and copy it for the service.':'No published email or specific service channel matches these choices yet. Use the official finders or add a verified contact.';
 const schoolChoice=state.levels.includes('school')?`<div class="field"><label for="recipient-school-board">Your school authority / board</label><select id="recipient-school-board" data-bind="schoolBoard"><option value="">Choose your actual school authority</option>${E.jurisdictions(state.province,'school').map(n=>`<option value="${esc(n)}" ${state.schoolBoard===n?'selected':''}>${esc(n)}</option>`).join('')}</select><small>${coverage.needsSchoolBoard?'Choose your board to see its contacts. Provincial services below do not identify your school board.':'Only contacts for the authority you chose are suggested. Confirm it serves your school.'}</small></div>`:'';
 return `<p class="section-kicker">STEP 03 / THE RIGHT OFFICES</p><h2>Choose who receives it.</h2><p class="panel-intro">Start with the offices most closely matched to your choices. Published role inboxes are preferred among equally relevant contacts. Select each recipient yourself.</p><div class="directory-callout"><div><b>${R.stats.uniqueEmails.toLocaleString()} distinct email addresses</b><p>Search by office, board, municipality, riding or representative. Each record includes its source and purpose.</p></div>${button('Search contact directory','directory-choose','secondary small')}</div><label class="checkrow"><input type="checkbox" id="opposition" data-bind="opposition" ${state.opposition?'checked':''}>Also show relevant opposition offices for oversight</label>${state.opposition&&['NT','NU'].includes(state.province)?notes('The Northwest Territories and Nunavut use consensus government and do not have an Official Opposition in the party-based sense.'):''}${notes('Check the current office and the contact’s purpose before sending. Access/privacy and other specialist inboxes are for their listed service. This directory has broad coverage, but it is not complete.','amber')}<p class="lookup-result" id="recipient-coverage" data-coverage="${coverage.status}">${esc(coverageText)}</p>${schoolChoice}
 ${groups.main.length?`<h3 class="contact-group">Suggested offices${count?' and your selections':''}</h3>${groups.main.map(contactCard).join('')}`:(coverage.status==='email'?notes('Review the additional offices below for a relevant email contact.'):'' )}
 ${groups.serviceRoutes.length?`<h3 class="contact-group">Other official service channels</h3>${groups.serviceRoutes.map(contactCard).join('')}`:''}
 ${groups.additional.length?`<details class="details additional-offices"><summary>Show ${groups.additional.length} additional office${groups.additional.length===1?'':'s'}</summary><div class="details-content"><p class="small">These may help with some concerns. Check each office’s responsibility before adding it.</p>${groups.additional.map(contactCard).join('')}</div></details>`:''}
 ${groups.finders.length?`<details class="details" ${!groups.main.length?'open':''}><summary>Official finders and contact pages (${groups.finders.length})</summary><div class="details-content">${groups.finders.map(contactCard).join('')}</div></details>`:''}

 <details class="details"><summary>Add a published office email</summary><div class="details-content"><p class="small muted">For an office missing from the directory, verify its public work email on the official website first.</p><div class="form-grid"><div class="field"><label for="custom-role">Office or position</label><input id="custom-role" placeholder="e.g. School board office" maxlength="160"></div><div class="field"><label for="custom-level">Level</label><select id="custom-level">${state.levels.map(l=>`<option value="${l}">${levelNames[l]}</option>`).join('')}</select></div></div><div class="field"><label for="custom-email">Published office / work email</label><input id="custom-email" type="email" placeholder="office@example.ca" maxlength="254"></div><div class="field"><label for="custom-source">Official source link</label><input id="custom-source" type="url" placeholder="https://…"></div><label class="checkrow"><input id="custom-confirm" type="checkbox">I checked that this is the office’s public professional contact.</label>${button('Add office','add-contact','secondary small')}<p class="error" id="custom-error" role="status"></p></div></details><div class="actions"><span class="small muted" id="selected-count">${count} email recipient${count===1?'':'s'} selected</span>${button('Write your message →','next')}</div>`;
}
function messagePanel(){const rec=E.selectedContacts(state),serviceRoutes=E.recipientGroups(state).serviceRoutes;const subjectBox=`<div class="field"><label for="subject">Subject</label><input id="subject" data-bind="subject" maxlength="200" value="${esc(state.subject)}" placeholder="Add a clear subject"></div>`;
return `<p class="section-kicker">STEP 04 / IN YOUR WORDS</p><h2>A clear message. Your voice.</h2><p class="panel-intro">Use a few prompts to build a letter, or write it yourself. The draft builder uses your words and a local template; it does not send them to an AI service.</p><div class="recipient-strip"><b>Recipients:</b> ${rec.length?rec.map(c=>`${state.recipientModes[c.id]==='cc'?'Cc':'To'}: ${esc(c.email)}`).join(' · '):'None selected. You can still write and copy a message for an official contact form.'} <button class="text-button" data-action="edit-contacts">Edit recipients</button></div>
${serviceRoutes.length?`<div class="note"><div><b>Other ways to contact this service</b><p class="small">Use the service’s published instructions. Where a form is offered, write your message below, choose Copy message and paste it there. Opening a page does not submit your message.</p>${serviceRoutes.map(c=>`<p><a href="${esc(E.safeURL(c.source))}" target="_blank" rel="noopener noreferrer">${esc(c.role)} ↗</a></p>`).join('')}</div></div>`:''}
${state.body&&state.draftContext&&state.draftContext!==[state.province,state.city,state.municipality||'',state.ward,state.issue].join('|')?notes('Your location or topic changed after this draft was built. Update the letter or rebuild it from the prompts before sending.','amber'):''}<div class="tab-toggle"><button data-editor="guide" class="${editor==='guide'?'active':''}" aria-pressed="${editor==='guide'}">Help me write</button><button data-editor="edit" class="${editor==='edit'?'active':''}" aria-pressed="${editor==='edit'}">Edit my email</button></div>
${editor==='guide'?`${field('topic','What is the issue?','A short, specific title')}${area('concern','What happened or needs to change?','Describe the concern in your own words. Include relevant dates or the service involved.')}${area('impact','How does it affect you or your community? <span class="optional">· optional</span>','Explain the effect without including sensitive identifiers.')}${area('request','What action would you like?','For example: review the service, explain the policy, or provide a timeline.')}<div class="form-grid">${field('name','Your name <span class="optional">· optional</span>','Your name')}<div class="field"><label for="tone">Tone</label><select id="tone" data-bind="tone"><option value="respectful" ${state.tone==='respectful'?'selected':''}>Respectful & constructive</option><option value="firm" ${state.tone==='firm'?'selected':''}>Firm & respectful</option></select></div></div><div class="field"><label for="language">Letter framework</label><select id="language" data-bind="language"><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="fr" ${state.language==='fr'?'selected':''}>Français</option></select><small>The framework changes language. Your own text is kept exactly as written; it is not translated.</small></div><label class="checkrow"><input id="includePostal" data-bind="includePostal" type="checkbox" ${state.includePostal?'checked':''}>Include my postal code in the letter</label>${button('Build my editable draft →','generate')}<p class="error" id="draft-error" role="status"></p>`:`${subjectBox}${area('body','Message','Write your message here.',14)}<p class="small muted">Review the wording, recipients and facts before opening your email app. You can attach files there.</p><div class="field"><label for="emailApp">Open with</label><select id="emailApp" data-bind="emailApp"><option value="default" ${state.emailApp==='default'?'selected':''}>My email app</option><option value="gmail" ${state.emailApp==='gmail'?'selected':''}>Gmail in browser</option><option value="outlook" ${state.emailApp==='outlook'?'selected':''}>Outlook in browser</option></select><small>Uses your existing signed-in account. No email password is stored here.</small></div><label class="checkrow"><input id="review-confirm" type="checkbox">I have reviewed the recipients and message.</label><a class="button" id="send-link" href="#" aria-disabled="true">Open email draft <span>↗</span></a><p id="send-error" class="error" role="status"></p>${notes('Opening a draft does not send it. Press Send in your email service when you are ready. If a long message is truncated by your email app, use Copy message below.')}<div class="row">${button('Copy message','copy','secondary small')}${button('Copy recipients','copy-recipients','secondary small')}${button('Save draft on this device','save','secondary small')}${button('Download .txt','download','secondary small')}${button('Email QR (opens email app)','share-email-qr','secondary small')}${button('CivicPost QR (opens draft)','share-draft','secondary small')}</div>`}
<div class="actions">${button('← Back to offices','back','link')}<span class="small muted">You decide when to send.</span></div>`;}
function renderSidebar(){const issue=D.issues.find(i=>i.id===state.issue),p=D.provinces.find(p=>p.code===state.province);$('#sidebar').innerHTML=`${state.city?`<div class="side-summary"><p class="summary-title">YOUR LETTER, SO FAR</p><div class="summary-item">${icon('pin')}<span>${esc(state.city)}, ${esc(state.province)}${state.ward?'<br><span class="muted">'+esc(state.ward)+'</span>':''}</span></div>${issue?`<div class="summary-item">${icon(issue.icon)}<span>${issue.name}</span></div>`:''}</div>`:''}<div class="side-card"><h3>Different levels.<br>Different responsibilities.</h3><div class="levels">${[['municipal','city','Your community','Roads, parks, transit & local services'],['provincial','building','Your province or territory','Education, health & provincial programs'],['federal','globe','Your country','Foreign affairs, citizenship & national policy']].map(([level,symbol,title,detail])=>`<div class="level-line ${!state.issue||state.levels.includes(level)?'relevant':''}"><div class="level-symbol">${icon(symbol)}</div><div><b>${title}</b><p>${detail}</p></div></div>`).join('')}</div><p class="small" style="margin-top:20px;margin-bottom:0">Some issues involve more than one level. <a href="${D.responsibilities}" target="_blank" rel="noopener noreferrer">How responsibility works ↗</a></p></div><div class="side-bottom">${icon('lock')}<p><b>Your message stays yours.</b><br>No account or email password needed. Nothing is sent automatically.</p></div>`;}
