function updateSend(){const a=$('#send-link');if(!a)return;try{const mail=E.mailto(state);let url=mail;const rec=E.selectedContacts(state);const to=rec.filter(c=>state.recipientModes[c.id]!=='cc').map(c=>c.email).join(','),cc=rec.filter(c=>state.recipientModes[c.id]==='cc').map(c=>c.email).join(',');if(state.emailApp==='gmail')url='https://mail.google.com/mail/?'+new URLSearchParams({view:'cm',fs:'1',to,cc,su:state.subject,body:state.body});if(state.emailApp==='outlook')url='https://outlook.live.com/mail/0/deeplink/compose?'+new URLSearchParams({to,cc,subject:state.subject,body:state.body});a.href=url;a.dataset.ready='true';a.setAttribute('aria-disabled',String(!$('#review-confirm')?.checked));$('#send-error').textContent='';}catch(err){a.href='#';a.dataset.ready='false';a.setAttribute('aria-disabled','true');$('#send-error').textContent=err.message;}}
function about(){window.CivicLegalContent?legalHome():modal('<h2>CivicPost Canada</h2><p>Independent and nonpartisan. Verify official sources and review before sending.</p>');}
function coverage(){
 if($('#dialog').open)$('#dialog').close();const stats=R.stats;
 modal(`<p class="section-kicker">CONTACT COVERAGE & SOURCES</p><h2>A directory you can inspect.</h2><div class="coverage-numbers"><div><strong>${stats.uniqueEmails.toLocaleString()}</strong><span>Distinct email addresses</span></div><div><strong>${stats.genericEmails.toLocaleString()}</strong><span>Office / role inboxes</span></div><div><strong>${stats.specialistEmails.toLocaleString()}</strong><span>Service-specific addresses</span></div></div><p>${stats.records.toLocaleString()} office records. A shared inbox may serve more than one office and is counted once in the distinct-address total. Service-specific contacts are included in the total, not added on top.</p><table class="coverage-table"><thead><tr><th>Level</th><th>Distinct emails</th><th>Office records</th></tr></thead><tbody>${Object.entries(stats.byLevel).map(([l,x])=>`<tr><td>${levelNames[l]||esc(l)}</td><td>${x.uniqueEmails.toLocaleString()}</td><td>${x.records.toLocaleString()}</td></tr>`).join('')}</tbody></table><details class="details"><summary>Coverage by province and territory</summary><table class="coverage-table"><tr><th>Province / territory</th><th>Distinct emails</th></tr>${D.provinces.map(p=>`<tr><td>${esc(p.name)}</td><td>${(stats.byProvince[p.code]?.uniqueEmails||0).toLocaleString()}</td></tr>`).join('')}<tr><td>Federal offices serving Canada</td><td>${(stats.byProvince.CA?.uniqueEmails||0).toLocaleString()}</td></tr></table></details><p><b>Snapshot retrieved ${esc(R.checked)}.</b> A retrieval date is not a guarantee that a source was recently updated, that an officeholder still serves, or that a mailbox accepts mail. Confirm the source before sending. Known unconfirmed officeholders are excluded. Ontario transition records require a fresh source check before use.</p><p>School records include trustees, board offices, individual school offices and district services; municipal records include council and administration. Access-to-information/privacy officers and program contacts have a specific purpose. City wards do not determine school boards, and a board headquarters address does not describe its service area.</p><div class="row">${button('Search public offices','directory-browse','secondary small')}<span class="small">Contacts are supplied by limited online lookups. No full directory download is offered.</span></div><h3>Source groups</h3><ul class="source-list">${R.sources.map(x=>`<li><a href="${esc(E.safeURL(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ↗</a><br><span class="small muted">${x.records.toLocaleString()} records · ${esc(x.kind)}</span></li>`).join('')}</ul><p class="small">Coverage remains uneven. Missing offices use official-directory links; these links are never counted as email contacts.</p>`);
}
let directoryUI={mode:'browse',province:'',level:'',jurisdiction:'',query:'',genericOnly:false,offset:0};
function openDirectory(mode){directoryUI={mode,province:state.province||'',level:mode==='choose'&&state.levels.length===1?state.levels[0]:'',jurisdiction:'',query:'',genericOnly:false,offset:0};if($('#dialog').open)$('#dialog').close();directoryModal();}
function directoryModal(){
 const f=directoryUI,levels=f.mode==='choose'?state.levels:Object.keys(levelNames),orgs=E.jurisdictions(f.province,f.level);
 const html=`<p class="section-kicker">SEARCH THE CONTACT DIRECTORY</p><h2>${f.mode==='choose'?'Find an office for your letter.':'Search public offices.'}</h2><p class="small muted">${f.mode==='choose'?'Showing contacts in your province and the levels chosen for your issue. Use the organization filter to find your actual board or council.':'Browse published professional contacts and check the source. Choose your location and issue to add recipients to a letter.'}</p><div class="form-grid"><div class="field"><label for="directory-province">Province / territory</label><select id="directory-province" data-directory-filter="province" ${f.mode==='choose'?'disabled':''}><option value="">Choose a province</option>${D.provinces.map(p=>`<option value="${p.code}" ${p.code===f.province?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="directory-level">Level</label><select id="directory-level" data-directory-filter="level"><option value="">All selected levels</option>${levels.map(l=>`<option value="${l}" ${f.level===l?'selected':''}>${levelNames[l]}</option>`).join('')}</select></div></div><div class="field"><label for="directory-organization">Organization / board / council</label><select id="directory-organization" data-directory-filter="jurisdiction"><option value="">All organizations</option>${orgs.map(o=>`<option value="${esc(o)}" ${o===f.jurisdiction?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div class="field"><label for="directory-search">Search office, riding, municipality, name or email</label><input id="directory-search" data-directory-query value="${esc(f.query)}" placeholder="e.g. Edmonton, education, Ward 3" maxlength="120" type="search"></div><label class="checkrow"><input type="checkbox" data-directory-generic ${f.genericOnly?'checked':''}>Only office / role inboxes</label><div id="directory-results" aria-live="polite"></div>`;
 $('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();renderDirectoryResults();
}
function renderDirectoryResults(){
 const f=directoryUI,res=E.directorySearch({...f,levels:f.mode==='choose'?state.levels:undefined,issue:f.mode==='choose'?state.issue:undefined,limit:24});
 $('#directory-results').innerHTML=`<p class="small"><b>${res.total.toLocaleString()} matching office records</b>${res.total?' · '+(f.offset+1)+'–'+Math.min(res.total,f.offset+24):''}</p>${res.results.map(c=>{const selected=state.selected.some(id=>(E.directoryById.get(id)||E.contactsFor(state).find(r=>r.id===id))?.email?.toLowerCase()===c.email.toLowerCase());return `<article class="directory-result"><div><h3>${esc(c.role)}${c.district?' — '+esc(c.district):''}</h3><p class="contact-jurisdiction">${esc(c.jurisdiction)} · ${esc(c.province||'Canada')}</p>${c.name?`<p class="small">${esc(c.name)}</p>`:''}<span class="chip">${c.emailType==='office'?'Office / role inbox':'Published work email'}</span>${c.specialist?'<span class="chip gray">Specific service only</span>':''}${c.schoolOffice?'<span class="chip gray">Individual school office</span>':''}${c.refreshAfter?'<span class="chip gray">Recheck from '+esc(c.refreshAfter)+'</span>':''}${c.continuityInferred?'<span class="chip gray">Reelected · retained office email</span>':''}${c.officeStaff?'<span class="chip gray">Office staff</span>':''}<span class="contact-email">${esc(c.email)}</span><p class="small muted">${esc(c.note||'')}</p>${!E.currentRecord(c)?'<p class="error">'+(c.refreshReview?.status==='needs-verification'||c.refreshStatus==='needs_verification'?'This office needs current verification and cannot be added.':'This office record is outside its verified term and cannot be added.')+'</p>':''}<p class="small">${esc(sourceLabel(c))} · <a href="${esc(E.safeURL(c.source))}" target="_blank" rel="noopener noreferrer">Source ↗</a> · Retrieved ${esc(c.checked)}${c.sourceDate?' · Source date '+esc(c.sourceDate):''}</p></div>${f.mode==='choose'?`<button class="button ${selected?'secondary':''} small" data-pick-contact="${esc(c.id)}" ${selected||!E.currentRecord(c)?'disabled':''}>${!E.currentRecord(c)?(c.refreshReview?.status==='needs-verification'||c.refreshStatus==='needs_verification'?'Needs verification':'Outside verified term'):selected?'Added':'Add to letter'}</button>`:''}</article>`;}).join('')}${!res.total?'<p>No matching email records. Try a broader search or the official directory for your jurisdiction.</p>':''}<div class="directory-pagination"><button class="button secondary small" data-directory-page="-1" ${f.offset===0?'disabled':''}>← Previous</button><span class="small">${res.total?'Page '+(Math.floor(f.offset/24)+1)+' of '+Math.ceil(res.total/24):'No results'}</span><button class="button secondary small" data-directory-page="1" ${f.offset+24>=res.total?'disabled':''}>Next →</button></div>`;
}
function showSaved(){modal(`<h2>Your saved drafts.</h2><p>Stored only on this device and browser profile. Loading replaces the current unsaved session.</p>${saved.length?saved.map((d,i)=>`<div class="saved-item"><b>${esc(d.title)}</b><p>${esc(d.date||'')}</p><div class="row"><button class="button small secondary" data-load="${i}">Load draft</button><button class="text-button" data-delete="${i}">Delete</button></div></div>`).join(''):'<p class="muted">No drafts yet. Save one from the email editor.</p>'}`);}
async function copyText(text){if(!text){toast('There is nothing to copy yet.');return;}try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{const a=document.createElement('textarea');a.value=text;a.style.position='fixed';a.style.left='-9999px';document.body.append(a);a.select();const ok=document.execCommand('copy');a.remove();if(ok)toast('Copied.');else modal(`<h2>Copy your text</h2><p>Select the text below and use your device’s Copy command.</p><textarea class="input" rows="12" style="width:100%">${esc(text)}</textarea>`);}}
function generate(){if(!state.concern.trim()){const el=$('#draft-error');if(el)el.textContent='Describe the concern first, so the letter reflects your actual issue.';return;}if(state.includePostal&&!E.postalValid(state.postal)){toast('Enter a valid postal code in Your location, or turn off its inclusion.');return;}if(state.body.trim()){modal(`<h2>Replace the current draft?</h2><p>Your edited email will be replaced with a new draft made from the prompts. Save or copy it first if you want to keep it.</p>${button('Replace with a new draft','confirm-generate')}`);return;}finishGenerate();}
function finishGenerate(){Object.assign(state,E.draft(state));state.draftContext=[state.province,state.city,state.municipality||'',state.ward,state.issue].join('|');editor='edit';if($('#dialog').open)$('#dialog').close();render();toast('Draft built. Edit it before opening your email app.');}
function addContact(){const role=$('#custom-role').value.trim(),email=$('#custom-email').value.trim(),source=E.safeURL($('#custom-source').value),level=$('#custom-level').value;const err=$('#custom-error');if(!role||!E.emailValid(email)||!source||!$('#custom-confirm').checked){err.textContent='Add an office name, a valid single email, an HTTPS source link, and confirm that you verified it.';return;}if(E.contactsFor(state).some(c=>c.email?.toLowerCase()===email.toLowerCase())){err.textContent='That email is already listed.';return;}const c={id:'custom-'+Date.now(),role,email,source,level,province:state.province,city:state.city,kind:'custom',checked:new Date().toISOString().slice(0,10),note:'Verified by you; not independently checked by CivicPost.'};state.custom.push(c);state.selected.push(c.id);render();toast('Office added and selected.');}
function applyLookupResult(result,offline=false){
 lookup=E.parseLookup(result.data,{trustedOfficeTypes:result.source==='bundled',origin:result.source==='bundled'?'the downloaded postal database':'Open North',checked:result.source==='bundled'?CivicDirectory.checked:result.fetchedAt.slice(0,10),recordSources:result.recordSources||[]});lookupResult=result;lookupOffline=offline;state.liveReps=lookup.reps;state.liveChosen=[];
 const p=D.provinces.find(p=>p.code===lookup.province||E.norm(p.name)===E.norm(lookup.province));
 if(p)state.province=p.code;
 state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';invalidate();
 state.city=lookup.city||'';state.locationConfirmed=false;locationStatus=lookup.city?'City suggested by the postal lookup. Confirm it before continuing.':'Enter your community; this lookup did not resolve one city.';
 lookupError='';
}
async function startLookup(){
 cancelLocationSuggestion();
 if(!CivicPostal.valid(state.postal)){lookupError='Enter a complete Canadian postal code, such as T5K 1E7.';render();return;}
 clearLookup();state.postal=CivicPostal.normalize(state.postal);state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';invalidate();
 lookupPending=true;const token=Symbol('postal-lookup');lookupToken=token;const postal=state.postal;lookupAbort=new AbortController();lookupStatus='Reading downloaded database…';render();
 const current=()=>token===lookupToken&&postal===CivicPostal.normalize(state.postal);
 try{
  const response=await CivicOffline.resolve(postal,{signal:lookupAbort.signal,onLocal:result=>{if(!current())return;applyLookupResult(result,true);lookupStatus='Database result ready. Checking the live API for updates…';render();}});
  if(!current())return;
  if(response.result.source==='bundled'){
   lookupStatus='Live lookup unavailable. Keeping the downloaded database result.';
   if(!lookupResult)applyLookupResult(response.result,true);
  }else if(lookupInteracted&&lookupResult){
   lookupUpdated=response.result;lookupStatus='Updated results are ready. Your current choices are kept until you choose to use the update.';
  }else {applyLookupResult(response.result);lookupStatus=response.result.source==='mixed'?'Live update added. Downloaded results are kept for levels the API did not return.':'Live API result loaded.';}
 }catch(err){if(!current()||err.code==='cancelled')return;lookupError=err.message;}
 finally{if(current()){lookupPending=false;lookupAbort=null;render();}}
}
function offlineCoverage(){
 const m=CivicOfflineData;
 modal(`<p class="section-kicker">DOWNLOADED POSTAL DATABASE</p><h2>${m.postalCodes.toLocaleString()} full postal codes.</h2><p>Included in the Android app. The webpage needs an initial online visit and a completed offline download before it can work without a connection. Browser storage can be cleared or evicted.</p><p>Postal source packaged ${esc(m.sourceSnapshot)}; original observation dates are not supplied. A postal point is an approximate location. A code can cross districts, and some source points are inaccurate.</p><table class="coverage-table"><tr><th>Offline boundary set</th><th>Districts</th></tr>${m.sets.map(s=>`<tr><td><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(s.city||s.province||'Canada')} · ${esc(levelNames[s.level])}</a></td><td>${s.atLarge?'City-wide':s.polygonCount}${s.validUntil?'<br>Through '+esc(s.validUntil):''}${s.validFrom?'<br>From '+esc(s.validFrom):''}${s.coverageNote?'<br>'+esc(s.coverageNote):''}</td></tr>`).join('')}</table><p>School-board boundaries and municipalities/provinces not listed above are not included. A missing offline district does not mean no representative exists; try the live API or an official finder.</p><p>Downloaded municipal boundaries cover 18 municipalities. The latest expansion adds contact and service coverage for the next ten municipalities by 2021 Census population; seven have downloaded ward candidates. Gatineau, Saskatoon and Vaughan use manual ward selection and official finders. Vancouver and Surrey have city-wide councils rather than wards. Surrey uses a 2021 boundary snapshot; current limits have not been independently confirmed. Montréal districts also identify the borough. Names and published emails are matched to the bundled contact directory. A district without an email still shows its official directory link. No email address is guessed.</p>${m.municipalExpansion?.length?`<h3>Latest ten-city expansion</h3><table class="coverage-table"><tr><th>City</th><th>Ward lookup</th></tr>${m.municipalExpansion.map(c=>`<tr><td>${esc(c.city)}</td><td>${c.wardLookup==='downloaded'?'Downloaded candidates':'Manual / official finder'}<br><small>${esc(c.note)}</small></td></tr>`).join('')}</table>`:''}<p>Postal data: <a href="https://www.geonames.org/" target="_blank" rel="noopener noreferrer">GeoNames</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. <a href="offline-postal/sources.html" target="_blank" rel="noopener noreferrer">Full source, licence and coverage notes ↗</a></p>`);
}
function refreshPostalFeedback(){
 const results=$('#postal-results'),status=$('#postal-status'),button=$('[data-action="lookup"]');
 if(results)results.innerHTML=(lookup?lookupChoices():'')+lookupRecovery();
 if(status)status.textContent=lookupError||lookupStatus;
 if(button){button.disabled=lookupPending;button.textContent=lookupPending?'Finding…':'Find districts';}
}
function lookupRecovery(){
 if(!CivicPostal.valid(state.postal))return '';
 const cache=CivicPostal.saved(state.postal),p=D.provinces.find(p=>p.code===state.province),city=E.cityFor(state);
 if(!cache&&!lookupError&&!lookupResult&&!lookupUpdated)return '';
 return `<div class="lookup-recovery"><div class="row">${lookupUpdated?button('Use updated API results','use-updated-lookup','secondary small'):''}${lookupResult&&!lookupOffline?button('Save this lookup for offline use','save-lookup','secondary small'):''}${cache?button('Use saved lookup','use-saved-lookup','secondary small')+button('Remove saved lookup','remove-saved-lookup','secondary small'):''}</div>${lookupResult&&!lookupOffline?'<p class="small muted">Saving keeps this postal code and its public representative results on this device. Offline results expire after 30 days. A new save replaces the previous one.</p>':''}${lookupError?`<p class="small">A failed lookup does not mean you have no representative. Check the service directly or use an official finder:</p><div class="row"><a class="button secondary small" href="${CivicPostal.url(state.postal,true)}" target="_blank" rel="noopener noreferrer">Open this postal lookup ↗</a><a class="button secondary small" href="${esc(D.federalMembers)}" target="_blank" rel="noopener noreferrer">Find my MP ↗</a>${p?`<a class="button secondary small" href="${esc(p.members)}" target="_blank" rel="noopener noreferrer">Find my ${esc(p.title)} ↗</a>`:''}${city?`<a class="button secondary small" href="${esc(city.wardFinder)}" target="_blank" rel="noopener noreferrer">Find my ward ↗</a>`:''}</div>`:''}</div>`;
}
function download(){const text='To: '+E.selectedContacts(state).filter(c=>state.recipientModes[c.id]!=='cc').map(c=>c.email).join(', ')+'\nCc: '+E.selectedContacts(state).filter(c=>state.recipientModes[c.id]==='cc').map(c=>c.email).join(', ')+'\nSubject: '+state.subject+'\n\n'+state.body;if(window.MoneySnapshotAndroid?.postMessage){window.MoneySnapshotAndroid.postMessage(JSON.stringify({type:'save',filename:'money-snapshot-civicpost-letter.txt',text}));return;}const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='CivicPost_Letter.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('input',e=>{if(lookupPending&&lookupResult)lookupInteracted=true;if(e.target.hasAttribute('data-directory-query')){directoryUI.query=e.target.value;directoryUI.offset=0;renderDirectoryResults();return;}const key=e.target.dataset.bind;if(!key)return;if(key==='province')return;if(key==='city'||key==='ward'){if(state[key]!==e.target.value){if(key==='city'){cancelLocationSuggestion();state.locationConfirmed=true;}state[key]=e.target.value;invalidate();if(key==='city'){state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';clearLookup();for(const field of ['provRiding','fedRiding','schoolBoard']){const el=$('#'+field);if(el)el.value='';}const w=$('#ward');if(w)w.value='';const city=E.cityFor(state);const help=$('#ward-help');if(help)help.innerHTML=city?'<a href="'+esc(city.wardFinder)+'" target="_blank" rel="noopener noreferrer">Find your ward on the official city website ↗</a>':'Not every municipality uses wards. A city name alone cannot identify your riding.';const list=$('#wards');if(list)list.innerHTML=(city?.wards||[]).map(v=>'<option value="'+esc(v)+'">').join('');refreshPostalFeedback();}else state.liveChosen=state.liveChosen.filter(id=>!state.liveReps.some(r=>r.id===id&&r.level==='municipal'));renderSidebar();}return;}state[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='postal'){cancelLocationSuggestion();clearLookup();state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';for(const id of ['ward','provRiding','fedRiding','schoolBoard']){const el=$('#'+id);if(el)el.value='';}invalidate();if(!state.province){const p=L.provinceFromPostal(state.postal);if(p){state.province=p;state.locationConfirmed=true;locationStatus='Province filled from your postal-code prefix. Enter or suggest your city.';const sel=$('#province');if(sel)sel.value=p;}}refreshPostalFeedback();renderSidebar();}if(['subject','body','emailApp'].includes(key))updateSend();});
document.addEventListener('change',e=>{if(lookupPending&&lookupResult)lookupInteracted=true;if(e.target.id==='remember-location'){rememberLocation=e.target.checked;if(!rememberLocation){try{localStorage.removeItem('civicpost-location-v1');}catch{}toast('Remembered location removed.');}return;}if(e.target.dataset.directoryFilter){directoryUI[e.target.dataset.directoryFilter]=e.target.value;directoryUI.offset=0;if(e.target.dataset.directoryFilter!=='jurisdiction')directoryUI.jurisdiction='';directoryModal();return;}if(e.target.hasAttribute('data-directory-generic')){directoryUI.genericOnly=e.target.checked;directoryUI.offset=0;renderDirectoryResults();return;}const key=e.target.dataset.bind;if(key){const val=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='province'&&val!==state.province){cancelLocationSuggestion();state.locationConfirmed=true;state.province=val;state.city='';state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';clearLookup();invalidate();render();return;}if(key==='city'&&val!==state.city){cancelLocationSuggestion();state.locationConfirmed=true;state.city=val;state.municipality='';state.ward='';state.provRiding='';state.fedRiding='';state.schoolBoard='';clearLookup();invalidate();render();return;}if(key==='ward'&&val!==state.ward){state.ward=val;state.liveChosen=state.liveChosen.filter(id=>!state.liveReps.some(r=>r.id===id&&r.level==='municipal'));invalidate();renderSidebar();}state[key]=val;if(['provRiding','fedRiding','schoolBoard'].includes(key)){const level={provRiding:'provincial',fedRiding:'federal',schoolBoard:'school'}[key];state.liveChosen=state.liveChosen.filter(id=>!state.liveReps.some(r=>r.id===id&&r.level===level));invalidate();}if(key==='serviceDetail'){invalidate();renderSidebar();}if(key==='opposition'||key==='schoolBoard'&&step===2)render();if(key==='emailApp')updateSend();}
 if(e.target.dataset.level){const l=e.target.dataset.level;state.levels=state.levels.filter(v=>v!==l);if(e.target.checked)state.levels.push(l);invalidate();renderSidebar();}
 if(e.target.dataset.contact){const id=e.target.dataset.contact;state.selected=state.selected.filter(x=>x!==id);if(e.target.checked)state.selected.push(id);e.target.closest('.contact-card').classList.toggle('selected',e.target.checked);if($('#selected-count'))$('#selected-count').textContent=E.selectedContacts(state).length+' email recipients selected';}
 if(e.target.dataset.mode)state.recipientModes[e.target.dataset.mode]=e.target.value;
 if(e.target.dataset.lookupLevel){const level=e.target.dataset.lookupLevel;state.liveChosen=state.liveChosen.filter(id=>!state.liveReps.some(r=>r.id===id&&r.level===level));const r=state.liveReps.find(r=>r.id===e.target.value);if(r){const group=lookupGroups(level).find(g=>g.reps.some(x=>x.id===r.id));state.liveChosen.push(...(group?.reps||[r]).map(x=>x.id));if(level==='municipal'){state.ward=r.district;if(lookup.city)state.city=lookup.city;}if(level==='provincial')state.provRiding=r.district;if(level==='federal')state.fedRiding=r.district;}invalidate();render();}
 if(e.target.id==='review-confirm')updateSend();});
document.addEventListener('click',async e=>{if(lookupPending&&lookupResult)lookupInteracted=true;const target=e.target.closest('button,a');if(!target)return;if(target.tagName==='A'){const href=target.getAttribute('href')||'';let url;try{url=new URL(href,location.href);}catch{e.preventDefault();return;}if(!['https:','mailto:'].includes(url.protocol)&&url.origin!==location.origin){e.preventDefault();toast('Only official HTTPS links and email drafts can open.');return;}}
 if(target.id==='directory-export'&&window.MoneySnapshotAndroid?.postMessage){e.preventDefault();try{const text=await (await fetch('./directory-contacts.csv')).text();window.MoneySnapshotAndroid.postMessage(JSON.stringify({type:'save',filename:'money-snapshot-civicpost-directory.txt',text}));toast('Save the directory as text; it uses CSV columns.');}catch{toast('The directory export could not be prepared.');}return;}if(target.dataset.pickContact){const c=E.directoryById.get(target.dataset.pickContact);if(c&&E.directoryEligible(c,state)){if(!state.directoryAdded.includes(c.id))state.directoryAdded.push(c.id);if(!state.selected.includes(c.id))state.selected.push(c.id);render();renderDirectoryResults();toast('Office added. Review its purpose and source before sending.');}return;}if(target.dataset.directoryPage){directoryUI.offset=Math.max(0,directoryUI.offset+24*Number(target.dataset.directoryPage));renderDirectoryResults();$('#directory-results').scrollIntoView({block:'start'});return;}
 if(target.dataset.step!==undefined){go(+target.dataset.step);return;}
 if(target.dataset.issue){state.issue=target.dataset.issue;state.serviceDetail='';state.levels=[...D.issues.find(i=>i.id===state.issue).levels];invalidate();render();return;}
 if(target.dataset.editor){editor=target.dataset.editor;render();return;}
 if(target.id==='send-link'){if(!$('#review-confirm')?.checked||target.dataset.ready!=='true'){e.preventDefault();toast('Select at least one To recipient, complete your message, and confirm your review.');return;}toast('Opening a draft. Send it from your email app when ready.');return;}
 if(target.dataset.load!==undefined){const d=saved[+target.dataset.load];if(!d)return;$('#dialog').close();modal(`<h2>Load this saved draft?</h2><p>This replaces the current session. Save your current message first if you want to keep it.</p><button class="button" data-confirm-load="${+target.dataset.load}">Load saved draft</button>`);return;}
 if(target.dataset.confirmLoad!==undefined){const d=saved[+target.dataset.confirmLoad];if(!d)return;const base=initial();for(const k of Object.keys(base)){if(typeof d.state[k]===typeof base[k])base[k]=d.state[k];}state=base;state.directoryAdded=Array.isArray(state.directoryAdded)?state.directoryAdded:[];state.liveReps=Array.isArray(state.liveReps)?state.liveReps:[];state.custom=Array.isArray(state.custom)?state.custom:[];state.selected=Array.isArray(state.selected)?state.selected:[];state.levels=Array.isArray(state.levels)?state.levels:[];state.liveChosen=Array.isArray(state.liveChosen)?state.liveChosen:[];step=3;editor='edit';$('#dialog').close();render();toast('Draft loaded. Recheck current office contacts before sending.');return;}
 if(target.dataset.delete!==undefined){saved.splice(+target.dataset.delete,1);saveList();$('#dialog').close();showSaved();return;}
 const action=target.dataset.action;
 if(action==='offline-coverage'){offlineCoverage();return;}
 if(action==='use-updated-lookup'&&lookupUpdated){applyLookupResult(lookupUpdated);lookupUpdated=null;lookupStatus='Updated results loaded. Review your district choices.';render();return;}
 if(action==='save-lookup'&&lookupResult){try{CivicPostal.save(lookupResult);render();toast('Lookup saved. Offline results expire after 30 days.');}catch{toast('This device could not save the lookup.');}return;}
 if(action==='use-saved-lookup'){const cached=CivicPostal.saved(state.postal);if(cached){const postal=state.postal;clearLookup();try{const local=await CivicOffline.lookup(postal);if(CivicPostal.normalize(state.postal)!==CivicPostal.normalize(postal))return;applyLookupResult(CivicOffline.mergeResults(local,cached),true);lookupStatus='Saved API results combined with the installed database. Confirm current offices before sending.';render();}catch{if(CivicPostal.normalize(state.postal)!==CivicPostal.normalize(postal))return;applyLookupResult(cached,true);render();}}else toast('No recent saved lookup matches this postal code.');return;}
 if(action==='remove-saved-lookup'){try{CivicPostal.remove();render();toast('Saved postal lookup removed.');}catch{toast('The saved lookup could not be removed.');}return;}

 if(action==='suggest-location')suggestLocation();if(action==='confirm-location'){state.locationConfirmed=true;locationStatus='City confirmed. Choose your actual ward, riding and school board below.';render();}if(action==='share-email-qr')showEmailQR();if(action==='share-draft')showShareDraft();if(action==='import-draft')showImportDraft();
 if(action==='directory-choose')openDirectory('choose');if(action==='directory-browse')openDirectory('browse');if(action==='next')go(Math.min(3,step+1));if(action==='back')go(Math.max(0,step-1));if(action==='edit-contacts')go(2);if(action==='lookup')startLookup();if(action==='add-contact')addContact();if(action==='generate')generate();if(action==='confirm-generate')finishGenerate();if(action==='copy')copyText('Subject: '+state.subject+'\n\n'+state.body);if(action==='copy-recipients')copyText(E.selectedContacts(state).map(c=>`${state.recipientModes[c.id]==='cc'?'Cc':'To'}: ${c.email}`).join('\n'));if(action==='download')download();if(action==='coverage')coverage();if(action==='save'){if(!state.body.trim()){toast('Write a message before saving a draft.');return;}saved.unshift({title:state.subject||'Untitled letter',date:new Date().toLocaleString(),state:JSON.parse(JSON.stringify(state))});saved=saved.slice(0,10);if(saveList())toast('Draft saved on this device.');}
});
document.addEventListener('keydown',e=>{if(e.target.id==='postal'&&e.key==='Enter'){e.preventDefault();if(!lookupPending)startLookup();}});
